    public static TreeNode buildTree(int[] preorder, int[] inorder) {
        List<Integer> pre = new ArrayList<>();
        List<Integer> in = new ArrayList<>();
        for (int i : preorder) {
            pre.add(i);
        }
        for (int i : inorder) {
            in.add(i);
        }
        return buildTree(pre, in);
    }

    private static TreeNode buildTree(List<Integer> pre, List<Integer> in) {
        if (pre.isEmpty()) {
            return null;
        }
        int rootVal = pre.get(0);
        TreeNode root = new TreeNode(rootVal);
        int index = in.indexOf(rootVal);
        List<Integer> leftIn = in.subList(0, index);
