        List<Integer> leftPre = pre.subList(1, index + 1);
        List<Integer> rightPre = pre.subList(index + 1, pre.size());
        root.left = buildTree(leftPre, leftIn);
        root.right = buildTree(rightPre, rightIn);
        return root;
